package com.bank.flow;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ControlFlowDemo {
    private static final Logger log = Logger.getLogger(ControlFlowDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Critical cleanup belongs in a shutdown hook (runs on System.exit),
        // NOT in another thread's finally (which exit skips).
        Runtime.getRuntime().addShutdownHook(new Thread(
                () -> log.info("Shutdown hook: audit flushed, pool closed")));

        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000.00"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000.00"));

        RoutingService routing = new RoutingService();

        // null instanceof → false, never throws: concise null-safe guard.
        log.info(() -> "route(null) = " + routing.route(null));
        log.info(() -> "route(instruction) = "
                + routing.route(new TransferInstruction(rajesh, priya, new BigDecimal("45000.00"))));

        TransferService service = new TransferService();
        boolean ok = service.transfer(rajesh, priya, new BigDecimal("45000.00"));
        log.info(() -> "transfer success = " + ok
                + ", Rajesh=" + rajesh.getBalance() + ", Priya=" + priya.getBalance());

        // Fatal-path demo: exit code 0 = success. Shutdown hook will run;
        // other threads' finally blocks would NOT.
        log.info("Completing normally with exit code 0");
        System.exit(0);
    }
}

