class RoutingService {
    private static final Logger log = Logger.getLogger(RoutingService.class.getName());

    // null instanceof returns false → one concise null-safe type check.
    String route(Object maybeInstruction) {
        if (maybeInstruction instanceof TransferInstruction ti) {
            // ti is guaranteed non-null and typed here.
            return "ROUTE " + ti.getFrom().getAccountId() + "->" + ti.getTo().getAccountId();
        }
        log.fine("Not a transfer instruction (or null) — default route");
        return "ROUTE_DEFAULT";
    }
}

// ─── Would be in service/TransferService.java in a real project ───
class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());

    // CORRECT: finally only cleans up; it does NOT return or throw, so the
    // real result and any exception survive.
    boolean transfer(Account from, Account to, BigDecimal amount) {
        boolean locked = acquireLock(from);
        try {
            if (from.getBalance().compareTo(amount) < 0) {
                return false;   // real result preserved — finally won't override
            }
            from.debit(amount);
            to.credit(amount);
            return true;
            // BUG (do NOT do this): a 'return' here in finally would override
            // this value and swallow any exception.
        } finally {
            releaseLock(from, locked);   // cleanup only
        }
    }

    private boolean acquireLock(Account a) {
        log.fine(() -> "lock " + a.getAccountId());
        return true;
    }
    private void releaseLock(Account a, boolean locked) {
        if (locked) log.fine(() -> "unlock " + a.getAccountId());
    }
}

// ─── Would be in util/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
